use crate::money::Money;
use crate::series::SeriesMeta;

/// Render a price held at a series' scale. Never feed this into arithmetic.
pub fn format_price(m: Money, meta: &SeriesMeta) -> String {
    let scale = meta.minor_per_unit.max(1);
    let whole = m.minor / scale;
    let frac = (m.minor % scale).abs();
    let width = (scale as f64).log10().round() as usize;
    format!("{whole}.{frac:0width$}")
}
